    "window.tkPv=function(){var e=$('tkpv');if(!e)return;var TC=curC(),t=TKS[TC],h=V('tk-h').trim().replace(/^@/,'')||'username';e.innerHTML='<span class=\"tkpb\">'+window.tkBadge(t.c,52)+'</span><div><b>'+esc(h)+tkB({id:'pv'+Math.random(),tick:TC})+'</b><small>'+t.n+' tick &middot; '+t.d+'</small></div><button type=\"button\" class=\"btn g sm\" onclick=\"tkPv()\">Replay</button>'};",
