let booted = false; // legacy scripts register global handlers, so they must run only once per page
 
export default function ThreadAdmin({ token, onTokenChange } = {}) {
  const host = useRef(null);
 
  useEffect(() => {
    if (booted) return;
    booted = true;
 
    document.title = "Thread Admin";
    if (!document.querySelector('link[data-thread-admin-font]')) {
      const link = document.createElement("link");
      link.rel = "stylesheet";
      link.href = FONT_HREF;
      link.setAttribute("data-thread-admin-font", "");
      document.head.appendChild(link);
    }
    const style = document.createElement("style");
    style.setAttribute("data-thread-admin", "");
    style.textContent = CSS;
    document.head.appendChild(style);
 
    SCRIPTS.forEach((code) => {
      const s = document.createElement("script");
      s.text = code;
      document.body.appendChild(s);
    });

    // Connect admin panel to real MongoDB users and moderation APIs
    const activeToken = (typeof token !== 'undefined' && token) || tok.get('thread_admin_jwt');
    if (activeToken) {
      setTimeout(() => initAdminClient(activeToken), 100);
    }

    // Non-intrusively hook admin login button to backend
    const pwInput = document.getElementById('pw');
    const loginBtn = document.querySelector('#login button.btn');
    const doAdminAuth = async () => {
      const password = pwInput ? pwInput.value.trim() : '';
      if (password) {
        try {
          const res = await call('/admin/login', { method: 'POST', body: { password } });
          if (res && res.token) {
            tok.set('thread_admin_jwt', res.token);
            if (typeof onTokenChange === 'function') onTokenChange(res.token);
            setTimeout(() => initAdminClient(res.token), 100);
          }
        } catch (e) {
          console.warn('Admin backend login failed, continuing with local flow:', e);
        }
      }
    };

    if (loginBtn && !loginBtn._backendHooked) {
      loginBtn._backendHooked = true;
      loginBtn.addEventListener('click', doAdminAuth);
    }
    if (pwInput && !pwInput._backendHooked) {
      pwInput._backendHooked = true;
      pwInput.addEventListener('keydown', (e) => {
        if (e.key === 'Enter') doAdminAuth();
      });
    }


    // Google Admin Login
    const googleBox = document.getElementById('google-admin-login');

    if (googleBox && !googleBox._googleLoaded) {
      googleBox._googleLoaded = true;

      const script = document.createElement('script');
      script.src = 'https://accounts.google.com/gsi/client';
      script.onload = () => {
        google.accounts.id.initialize({
          client_id: '611732788399-2bkhsdo1l25tn0b7mbaa11qfas57924b.apps.googleusercontent.com',
          callback: async (response) => {
            try {
              const payload = JSON.parse(atob(response.credential.split('.')[1]));

              const res = await call('/admin/google', {
                method: 'POST',
                body: { email: payload.email }
              });

              if (res.token) {
                tok.set('thread_admin_jwt', res.token);
                if (typeof onTokenChange === 'function') onTokenChange(res.token);
                setTimeout(() => initAdminClient(res.token), 100);
              }
            } catch(e) {
              console.warn('Google admin login failed', e);
            }
          }
        });

        google.accounts.id.renderButton(
          googleBox,
          {theme:'outline', size:'large', width:300}
        );
      };

      document.head.appendChild(script);
    }
  }, []);
 
  return <div ref={host} dangerouslySetInnerHTML={{ __html: MARKUP }} />;
}